solution:
from collections import Counter


def most_common(words):
    return Counter(words).most_common(1)[0][0]

alt:
def most_common(words):
    best = None
    best_count = 0
    for w in set(words):
        if words.count(w) > best_count:
            best, best_count = w, words.count(w)
    return best
